#pragma once
#include <JuceHeader.h>
#include <atomic>
#include <cmath>
namespace fx{struct StereoLevels{float left=0,right=0;};class AudioVisualState{public:void captureInput(const juce::AudioBuffer<float>&b)noexcept{cap(b,inL,inR);}void captureOutput(const juce::AudioBuffer<float>&b)noexcept{cap(b,outL,outR);}StereoLevels getInputLevels()const noexcept{return{inL.load(),inR.load()};}StereoLevels getOutputLevels()const noexcept{return{outL.load(),outR.load()};}private:static float lev(const juce::AudioBuffer<float>&b,int c)noexcept{if(c<0||c>=b.getNumChannels()||b.getNumSamples()<=0)return 0;float p=b.getMagnitude(c,0,b.getNumSamples()),r=b.getRMSLevel(c,0,b.getNumSamples()),a=juce::jmax(p*.72f,r*1.35f),d=juce::Decibels::gainToDecibels(a,-60.f);return juce::jlimit(0.f,1.f,juce::jmap(d,-60.f,0.f,0.f,1.f));}static void cap(const juce::AudioBuffer<float>&b,std::atomic<float>&l,std::atomic<float>&r)noexcept{int rc=b.getNumChannels()>1?1:0;l.store(lev(b,0));r.store(lev(b,rc));}std::atomic<float>inL{0},inR{0},outL{0},outR{0};};struct StereoFieldSnapshot{float correlation=1,width=0,balance=0;};class StereoFieldState{public:void capture(const juce::AudioBuffer<float>&b)noexcept{if(b.getNumChannels()<2||b.getNumSamples()<=0){c.store(1);w.store(0);bal.store(0);return;}double le=0,re=0,ce=0,me=0,se=0;for(int i=0;i<b.getNumSamples();++i){float l=b.getSample(0,i),r=b.getSample(1,i),m=.5f*(l+r),s=.5f*(l-r);le+=l*l;re+=r*r;ce+=l*r;me+=m*m;se+=s*s;}double d=std::sqrt(le*re);c.store(d>1e-9?(float)juce::jlimit(-1.,1.,ce/d):1.f);w.store((float)juce::jlimit(0.,1.5,se/juce::jmax(1e-9,me)));bal.store((float)juce::jlimit(-1.,1.,(re-le)/juce::jmax(1e-9,le+re)));}StereoFieldSnapshot getSnapshot()const noexcept{return{c.load(),w.load(),bal.load()};}private:std::atomic<float>c{1},w{0},bal{0};};}
